/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo, available_timezones
import cadence

for zone in (\"\", \"Europe\", \"America/Argentina\", \"posixrules\", \"zone.tab\", \"\\x00\", \"UTC\\x00\"):
    try:
        print(repr(zone), cadence.occurrences({\"timezone\": zone, \"rules\": []},
              \"2025-01-01T00:00Z\", \"2025-01-02T00:00Z\"))
    except Exception as exc:
        print(repr(zone), type(exc).__name__, str(exc))

for year in (1800, 1900, 1915):
    for name in sorted(available_timezones()):
        zone = ZoneInfo(name)
        offset = datetime(year, 1, 1, tzinfo=zone).utcoffset()
        if -timedelta(minutes=1) < offset < timedelta(0):
            print(\"Negative sub-minute offset\", year, name, offset)
PY"

